/** A singly linked list node used by the list problems. Provided; nothing to implement here. */
final class Node {
    public int value;
    public Node next;

    public Node(int value) {
        this.value = value;
    }

    public static Node of(int... values) {
        Node dummy = new Node(0);
        Node tail = dummy;
        for (int v : values) {
            tail.next = new Node(v);
            tail = tail.next;
        }
        return dummy.next;
    }

    public static java.util.List<Integer> toList(Node head) {
        java.util.List<Integer> out = new java.util.ArrayList<>();
        for (Node n = head; n != null; n = n.next) {
            out.add(n.value);
        }
        return out;
    }
}


final class NO_PUBLIC_CLASS_FOUND {
    static void show(Object o) {
        if (o instanceof int[] a) {
            System.out.println(Arrays.toString(a));
        } else if (o instanceof long[] a) {
            System.out.println(Arrays.toString(a));
        } else if (o instanceof double[] a) {
            System.out.println(Arrays.toString(a));
        } else {
            System.out.println(o);
        }
    }

    static void within(long millis, Supplier<Object> test) {
        CompletableFuture<Object> result = new CompletableFuture<>();
        Thread worker = new Thread(() -> {
            try {
                result.complete(test.get());
            } catch (Throwable e) {
                result.completeExceptionally(e);
            }
        });
        worker.setDaemon(true);
        worker.start();
        try {
            show(result.get(millis, TimeUnit.MILLISECONDS));
        } catch (TimeoutException e) {
            System.out.println("Too slow: no answer within " + millis / 1000 + " s");
        } catch (ExecutionException e) {
            System.out.println(e.getCause().getClass().getSimpleName());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
