question.answer:
/**
 * Week 15. Pattern: dummy head and splicing.
 * <p>
 * Merge two sorted linked lists into one sorted list by relinking the existing nodes (no new nodes except an
 * optional dummy head).
 */
public final class MergeSortedLists {

    private MergeSortedLists() {
    }

    public static Node merge(Node a, Node b) {
        //>>
        Node dummy = new Node(0);
        Node tail = dummy;
        while (a != null && b != null) {
            if (a.value <= b.value) {
                tail.next = a;
                a = a.next;
            } else {
                tail.next = b;
                b = b.next;
            }
            tail = tail.next;
        }
        tail.next = a != null ? a : b;
        return dummy.next;
        //<<
    }
}

testcode.text:
// The merged list must reuse the existing nodes.
Node a = Node.of(1);
Node b = Node.of(2);
Node merged = MergeSortedLists.merge(a, b);
System.out.println((merged == a) + " " + (merged.next == b));

