question.answer:
import java.math.BigDecimal;
import java.time.Instant;
import java.util.Comparator;
import java.util.List;

/**
 * Week 14. Pattern: Comparator composition.
 * <p>
 * Sort transactions for an investigation report: largest amount first; for equal amounts (compare with
 * {@code compareTo}, so 10.0 equals 10.00), earliest time first; then reference ascending. Return a new list;
 * don't modify the input.
 */
public final class StatementOrdering {

    public record Txn(String reference, BigDecimal amount, Instant at) {
    }

    private StatementOrdering() {
    }

    public static List<Txn> sorted(List<Txn> txns) {
        //>>
        return txns.stream()
                .sorted(Comparator.comparing(Txn::amount, Comparator.reverseOrder())
                        .thenComparing(Txn::at)
                        .thenComparing(Txn::reference))
                .toList();
        //<<
    }
}

testcode.text:
List<StatementOrdering.Txn> input = new ArrayList<>(List.of(
        new StatementOrdering.Txn("C", new BigDecimal("10.00"), Instant.parse("2026-01-01T10:00:00Z")),
        new StatementOrdering.Txn("A", new BigDecimal("500.00"), Instant.parse("2026-01-01T09:00:00Z")),
        new StatementOrdering.Txn("B", new BigDecimal("10.0"), Instant.parse("2026-01-01T09:00:00Z")),
        new StatementOrdering.Txn("D", new BigDecimal("10.00"), Instant.parse("2026-01-01T09:00:00Z"))));
System.out.println(StatementOrdering.sorted(input).stream().map(StatementOrdering.Txn::reference).toList());

// The input list must not change.
List<StatementOrdering.Txn> input = new ArrayList<>(List.of(
        new StatementOrdering.Txn("C", new BigDecimal("10.00"), Instant.parse("2026-01-01T10:00:00Z")),
        new StatementOrdering.Txn("A", new BigDecimal("500.00"), Instant.parse("2026-01-01T09:00:00Z"))));
StatementOrdering.sorted(input);
System.out.println(input.stream().map(StatementOrdering.Txn::reference).toList());

